#pragma once
#include "model.hpp"
#include <cstring>
namespace vamp {
// Inspect PE exports without loading code. Dependency DLLs are never launched by
// the catalog scanner; a real plugin is still validated in an isolated process.
inline bool vst2Candidate(const fs::path&path){HANDLE file=CreateFileW(path.c_str(),GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);if(file==INVALID_HANDLE_VALUE)return false;LARGE_INTEGER size{};HANDLE mapping=nullptr;const uint8_t*data=nullptr;bool found=false;if(GetFileSizeEx(file,&size)&&size.QuadPart>=sizeof(IMAGE_DOS_HEADER)&&size.QuadPart<=UINT32_MAX)mapping=CreateFileMappingW(file,nullptr,PAGE_READONLY,0,0,nullptr);if(mapping)data=(const uint8_t*)MapViewOfFile(mapping,FILE_MAP_READ,0,0,0);if(data){auto range=[&](uint64_t at,uint64_t n){return at<=(uint64_t)size.QuadPart&&n<=(uint64_t)size.QuadPart-at;};auto*dos=(const IMAGE_DOS_HEADER*)data;if(dos->e_magic==IMAGE_DOS_SIGNATURE&&dos->e_lfanew>=0&&range(dos->e_lfanew,sizeof(IMAGE_NT_HEADERS64))){auto*nt=(const IMAGE_NT_HEADERS64*)(data+dos->e_lfanew);if(nt->Signature==IMAGE_NT_SIGNATURE&&nt->FileHeader.Machine==IMAGE_FILE_MACHINE_AMD64&&nt->OptionalHeader.Magic==IMAGE_NT_OPTIONAL_HDR64_MAGIC&&nt->FileHeader.NumberOfSections<=96){auto*sections=(const IMAGE_SECTION_HEADER*)((const uint8_t*)&nt->OptionalHeader+nt->FileHeader.SizeOfOptionalHeader);auto sectionOffset=(const uint8_t*)sections-data;if(range(sectionOffset,sizeof(IMAGE_SECTION_HEADER)*nt->FileHeader.NumberOfSections)){auto rva=[&](uint32_t value,uint64_t bytes)->const uint8_t*{if(value<nt->OptionalHeader.SizeOfHeaders&&range(value,bytes))return data+value;for(int i=0;i<nt->FileHeader.NumberOfSections;i++){auto&s=sections[i];if(value>=s.VirtualAddress&&(uint64_t)value-s.VirtualAddress+bytes<=s.SizeOfRawData){uint64_t offset=(uint64_t)s.PointerToRawData+value-s.VirtualAddress;if(range(offset,bytes))return data+offset;}}return nullptr;};auto entry=nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT];auto*exports=(const IMAGE_EXPORT_DIRECTORY*)rva(entry.VirtualAddress,sizeof(IMAGE_EXPORT_DIRECTORY));if(exports&&exports->NumberOfNames<=65536){auto*names=(const DWORD*)rva(exports->AddressOfNames,(uint64_t)exports->NumberOfNames*4);if(names)for(DWORD i=0;i<exports->NumberOfNames;i++){auto*name=rva(names[i],14);if(name&&(!memcmp(name,"VSTPluginMain\0",14)||!memcmp(name,"main\0",5))){found=true;break;}}}}}}UnmapViewOfFile(data);}if(mapping)CloseHandle(mapping);CloseHandle(file);return found;}
}
